CREATE TABLE storage_settings(id INTEGER PRIMARY KEY CHECK(id=1),multi_account_enabled INTEGER NOT NULL DEFAULT 0 CHECK(multi_account_enabled IN(0,1)),autodelete_enabled INTEGER NOT NULL DEFAULT 0 CHECK(autodelete_enabled=0),dry_run INTEGER NOT NULL DEFAULT 1 CHECK(dry_run=1));
INSERT INTO storage_settings(id) VALUES(1);
CREATE TABLE storage_nodes(id TEXT PRIMARY KEY,provider TEXT NOT NULL CHECK(provider IN('r2','s3')),account_id TEXT NOT NULL,bucket_name TEXT NOT NULL,endpoint TEXT,credential_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','readonly','disabled')),priority INTEGER NOT NULL,quota_bytes INTEGER NOT NULL CHECK(quota_bytes>0),used_bytes INTEGER NOT NULL DEFAULT 0 CHECK(used_bytes>=0),reserved_bytes INTEGER NOT NULL DEFAULT 0 CHECK(reserved_bytes>=0),last_reconciled_at TEXT,CHECK(used_bytes+reserved_bytes<=quota_bytes));
CREATE TRIGGER single_active_storage BEFORE INSERT ON storage_nodes WHEN NEW.status='active' AND (SELECT multi_account_enabled FROM storage_settings WHERE id=1)=0 BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM storage_nodes WHERE status='active') THEN RAISE(ABORT,'MULTI_NODE_DISABLED') END; END;
CREATE TRIGGER single_active_storage_update BEFORE UPDATE ON storage_nodes WHEN NEW.status='active' AND (SELECT multi_account_enabled FROM storage_settings WHERE id=1)=0 BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM storage_nodes WHERE status='active' AND id<>NEW.id) THEN RAISE(ABORT,'MULTI_NODE_DISABLED') END; END;
INSERT INTO storage_nodes(id,provider,account_id,bucket_name,credential_ref,status,priority,quota_bytes) VALUES('primary','r2','binding-account','PRIMARY_STORAGE','binding:PRIMARY_STORAGE','active',1,9000000000);
